/**
 * Minimal, dependency-free STL reader / writer.
 *
 * Both ASCII and binary files are supported. The parsed representation keeps
 * the per-solid structure of ASCII files because CityFFD / CityBEM rely on one
 * `solid bN ... endsolid bN` block per building.
 *
 * Solid shape:
 *   { name: string, positions: Float32Array (9 floats per triangle), count: number }
 */

const HEADER_BYTES = 80
const TRIANGLE_BYTES = 50

/**
 * Decide whether an ArrayBuffer holds a binary STL. The byte-length check is
 * authoritative; falling back to "does it look like text" handles binary
 * files that start with the word "solid" (they exist in the wild).
 */
/**
 * Input: writeBinarySTL([{ name: "b0", positions: Float32Array.of(0,0,0, 1,0,0, 0,1,0), count: 1 }]). Output: true.
 */
export function isBinarySTL(buffer) {
  if (buffer.byteLength < HEADER_BYTES + 4) return false
  const view = new DataView(buffer)
  const n = view.getUint32(HEADER_BYTES, true)
  if (HEADER_BYTES + 4 + n * TRIANGLE_BYTES === buffer.byteLength) return true
  // Text files never contain NUL bytes; scan the first KB.
  const bytes = new Uint8Array(buffer, 0, Math.min(1024, buffer.byteLength))
  for (let i = 0; i < bytes.length; i++) {
    if (bytes[i] === 0) return true
  }
  return false
}

/**
 * Read the triangle count and little-endian vertex floats; stored normals are ignored.
 * Input: an 84 + 50 byte binary STL with one triangle. Output: { format: "binary", solids: [{ name: "binary", positions: Float32Array(9), count: 1 }], triangleCount: 1 }.
 */
export function parseBinarySTL(buffer, name = 'binary') {
  if (buffer.byteLength < 84) throw new Error('Binary STL header is truncated')
  const view = new DataView(buffer)
  const count = view.getUint32(HEADER_BYTES, true)
  if (!count) throw new Error('STL must contain at least one triangle')
  const expected = HEADER_BYTES + 4 + count * TRIANGLE_BYTES
  if (expected > buffer.byteLength) {
    throw new Error(`Binary STL is truncated (expected ${expected} bytes, got ${buffer.byteLength})`)
  }
  const positions = new Float32Array(count * 9)
  let offset = HEADER_BYTES + 4
  for (let t = 0; t < count; t++) {
    offset += 12 // skip stored normal, recomputed on write
    for (let k = 0; k < 9; k++) {
      positions[t * 9 + k] = view.getFloat32(offset, true)
      if (!Number.isFinite(positions[t * 9 + k])) throw new Error('STL vertices must be finite numbers')
      offset += 4
    }
    offset += 2 // attribute byte count
  }
  const headerBytes = new Uint8Array(buffer, 0, HEADER_BYTES)
  let header = ''
  for (let i = 0; i < HEADER_BYTES && headerBytes[i] !== 0; i++) {
    header += String.fromCharCode(headerBytes[i])
  }
  return {
    format: 'binary',
    header: header.trim(),
    solids: [{ name, positions, count }],
    triangleCount: count,
  }
}

const VERTEX_RE = /vertex\s+([-+\d.eE]+)\s+([-+\d.eE]+)\s+([-+\d.eE]+)$/y

/**
 * Collect vertex triples between solid/endsolid lines and reject incomplete triangles.
 * Input: "solid b0\nvertex 0 0 0\nvertex 1 0 0\nvertex 0 1 0\nendsolid b0". Output: one named solid with count: 1 and 9 vertex coordinates.
 */
export function parseAsciiSTL(text) {
  const solids = []
  let current = null
  let coords = []
  let triangleCount = 0

  const flush = () => {
    if (!current) return
    if (coords.length % 9) throw new Error('ASCII STL contains an incomplete triangle')
    const count = coords.length / 9
    current.positions = Float32Array.from(coords)
    if (!current.positions.every(Number.isFinite)) throw new Error('STL vertices must be finite numbers')
    current.count = count
    triangleCount += count
    solids.push(current)
    current = null
    coords = []
  }

  const lines = text.split(/\r?\n/)
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (!line) continue
    if (line.startsWith('vertex')) {
      VERTEX_RE.lastIndex = 0
      const m = VERTEX_RE.exec(line)
      if (!m) throw new Error(`Malformed vertex on line ${i + 1}: "${line}"`)
      if (!current) current = { name: 'unnamed', positions: null, count: 0 }
      coords.push(+m[1], +m[2], +m[3])
    } else if (line.startsWith('solid')) {
      flush()
      current = { name: line.slice(5).trim() || `solid${solids.length}`, positions: null, count: 0 }
    } else if (line.startsWith('endsolid')) {
      flush()
    }
    // facet / outer loop / endloop / endfacet lines carry no data we need
  }
  flush()

  if (solids.length === 0) {
    throw new Error('No solids found in ASCII STL')
  }
  if (!triangleCount) throw new Error('STL must contain at least one triangle')
  return { format: 'ascii', header: '', solids, triangleCount }
}

/**
 * Parse an STL held in an ArrayBuffer (binary or ASCII).
 * @param {ArrayBuffer} buffer
 * @param {string} [fallbackName] name for binary files (they have no solid names)
 */
/**
 * Input: new TextEncoder().encode("solid b0\nvertex 0 0 0\nvertex 1 0 0\nvertex 0 1 0\nendsolid b0").buffer. Output: format "ascii", triangleCount 1.
 */
export function parseSTL(buffer, fallbackName = 'model') {
  if (!(buffer instanceof ArrayBuffer)) {
    throw new Error('parseSTL expects an ArrayBuffer')
  }
  if (isBinarySTL(buffer)) return parseBinarySTL(buffer, fallbackName)
  const text = new TextDecoder('utf-8').decode(new Uint8Array(buffer))
  return parseAsciiSTL(text)
}

/**
 * Scan all vertices for min/max on each STL axis.
 * Input: [{ positions: Float32Array.of(0,0,0, 1,2,3) }]. Output: { x_min: 0, x_max: 1, y_min: 0, y_max: 2, z_min: 0, z_max: 3 }.
 */
export function computeBounds(solids) {
  const b = {
    x_min: Infinity,
    x_max: -Infinity,
    y_min: Infinity,
    y_max: -Infinity,
    z_min: Infinity,
    z_max: -Infinity,
  }
  for (const s of solids) {
    const p = s.positions
    for (let i = 0; i < p.length; i += 3) {
      if (p[i] < b.x_min) b.x_min = p[i]
      if (p[i] > b.x_max) b.x_max = p[i]
      if (p[i + 1] < b.y_min) b.y_min = p[i + 1]
      if (p[i + 1] > b.y_max) b.y_max = p[i + 1]
      if (p[i + 2] < b.z_min) b.z_min = p[i + 2]
      if (p[i + 2] > b.z_max) b.z_max = p[i + 2]
    }
  }
  if (!isFinite(b.x_min)) Object.keys(b).forEach((k) => (b[k] = 0))
  return b
}

/**
 * Concatenate the solids of several parsed files. Duplicate solid names are
 * made unique (they would otherwise be ambiguous for CityFFD), optionally by
 * prefixing every solid with its file name.
 *
 * @param {Array<{name:string, parsed:object}>} files
 * @param {{prefixWithFile?:boolean}} [options]
 */
/**
 * Input: a.stl and b.stl each containing solid "b0". Output: solids named "b0", "b0_1"; vertex arrays are shared without modification.
 */
export function mergeParsed(files, options = {}) {
  const used = new Map()
  const solids = []
  for (const file of files) {
    const stem = (file.name || 'file').replace(/\.[^.]+$/, '').replace(/\s+/g, '_')
    for (const s of file.parsed.solids) {
      let name = options.prefixWithFile ? `${stem}_${s.name}` : s.name
      if (used.has(name)) {
        let n = used.get(name) + 1
        while (used.has(`${name}_${n}`)) n++
        used.set(name, n)
        name = `${name}_${n}`
      }
      used.set(name, 0)
      solids.push({ name, positions: s.positions, count: s.count })
    }
  }
  return solids
}

function normalOf(p, i, out) {
  const ax = p[i],
    ay = p[i + 1],
    az = p[i + 2]
  const ux = p[i + 3] - ax,
    uy = p[i + 4] - ay,
    uz = p[i + 5] - az
  const vx = p[i + 6] - ax,
    vy = p[i + 7] - ay,
    vz = p[i + 8] - az
  let nx = uy * vz - uz * vy
  let ny = uz * vx - ux * vz
  let nz = ux * vy - uy * vx
  const len = Math.sqrt(nx * nx + ny * ny + nz * nz)
  if (len > 1e-20) {
    nx /= len
    ny /= len
    nz /= len
  } else {
    nx = ny = nz = 0
  }
  out[0] = nx
  out[1] = ny
  out[2] = nz
  return out
}

function fmt(n, precision) {
  const v = +n.toFixed(precision)
  return v === 0 ? '0' : String(v)
}

/**
 * Serialise solids to ASCII STL, one `solid` block per entry.
 * @param {Array} solids
 * @param {{precision?:number}} [options]
 */
/**
 * Input: [{ name: "b0", positions: Float32Array.of(0,0,0, 1,0,0, 0,1,0), count: 1 }]. Output: ASCII text starting "solid b0", with one recomputed normal and facet.
 */
export function writeAsciiSTL(solids, options = {}) {
  const precision = options.precision === undefined ? 5 : options.precision
  const out = []
  const n = [0, 0, 0]
  for (const s of solids) {
    out.push(`solid ${s.name}`)
    const p = s.positions
    for (let i = 0; i < p.length; i += 9) {
      normalOf(p, i, n)
      out.push(
        `  facet normal ${fmt(n[0], precision)} ${fmt(n[1], precision)} ${fmt(n[2], precision)}`,
        '    outer loop',
        `      vertex ${fmt(p[i], precision)} ${fmt(p[i + 1], precision)} ${fmt(p[i + 2], precision)}`,
        `      vertex ${fmt(p[i + 3], precision)} ${fmt(p[i + 4], precision)} ${fmt(p[i + 5], precision)}`,
        `      vertex ${fmt(p[i + 6], precision)} ${fmt(p[i + 7], precision)} ${fmt(p[i + 8], precision)}`,
        '    endloop',
        '  endfacet',
      )
    }
    out.push(`endsolid ${s.name}`)
  }
  return out.join('\n') + '\n'
}

/**
 * Serialise solids to a single binary STL (solid names are lost by design of
 * the binary format).
 * @returns {ArrayBuffer}
 */
/**
 * Input: one solid with count: 1 and 9 vertex floats. Output: an ArrayBuffer of 134 bytes with triangle count 1 at byte 80.
 */
export function writeBinarySTL(solids, header = 'CityFFD STL') {
  let total = 0
  for (const s of solids) total += s.count
  const buffer = new ArrayBuffer(HEADER_BYTES + 4 + total * TRIANGLE_BYTES)
  const view = new DataView(buffer)
  const bytes = new Uint8Array(buffer)
  const hdr = header.slice(0, HEADER_BYTES)
  for (let i = 0; i < hdr.length; i++) bytes[i] = hdr.charCodeAt(i) & 0xff
  view.setUint32(HEADER_BYTES, total, true)
  let offset = HEADER_BYTES + 4
  const n = [0, 0, 0]
  for (const s of solids) {
    const p = s.positions
    for (let i = 0; i < p.length; i += 9) {
      normalOf(p, i, n)
      view.setFloat32(offset, n[0], true)
      offset += 4
      view.setFloat32(offset, n[1], true)
      offset += 4
      view.setFloat32(offset, n[2], true)
      offset += 4
      for (let k = 0; k < 9; k++) {
        view.setFloat32(offset, p[i + k], true)
        offset += 4
      }
      view.setUint16(offset, 0, true)
      offset += 2
    }
  }
  return buffer
}

/**
 * Read a File / Blob as ArrayBuffer (promise based, no fixed sleeps).
 */
/**
 * Input: a browser File containing an STL. Output: Promise<ArrayBuffer> containing its bytes; read failures reject.
 */
export function readFileAsArrayBuffer(file) {
  if (typeof file.arrayBuffer === 'function') return file.arrayBuffer()
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(reader.result)
    reader.onerror = () => reject(reader.error || new Error('Could not read file'))
    reader.readAsArrayBuffer(file)
  })
}

/**
 * Translate a model's solids inside the STL frame (X east, Y up, Z south).
 * `offset` is [east, up, south] in metres; when `center` is true the model's
 * horizontal bounding-box centre is moved to the offset, otherwise its origin.
 */
/**
 * Input: one vertex [1,2,3], offset [10,0,-5], center false. Output: a new vertex [11,2,-2]; input positions stay unchanged.
 */
export function translateSolids(solids, offset, center = false) {
  const b = computeBounds(solids)
  const cx = center ? (b.x_min + b.x_max) / 2 : 0
  const cz = center ? (b.z_min + b.z_max) / 2 : 0
  return solids.map((s) => {
    const p = new Float32Array(s.positions.length)
    for (let i = 0; i < p.length; i += 3) {
      p[i] = s.positions[i] - cx + offset[0]
      p[i + 1] = s.positions[i + 1] + (offset[1] || 0)
      p[i + 2] = s.positions[i + 2] - cz + offset[2]
    }
    return { name: s.name, positions: p, count: s.count }
  })
}
