<script setup>
import { computed, ref, shallowRef } from 'vue'
import { parseSTL, computeBounds, writeAsciiSTL, writeBinarySTL } from './stlio.js'
import { stlFootprints } from './stlFootprints.js'
import { downloadFile } from '../shared/download.js'

const source = shallowRef(null)
const loading = ref(false),
  exporting = ref(false),
  error = ref(''),
  result = ref('')
const action = ref('binary'),
  latitude = ref(45.49556),
  longitude = ref(-73.57825)
const busy = computed(() => loading.value || exporting.value)
const boundsColumns = [
  { key: 'axis', label: 'Axis' },
  { key: 'min', label: 'Min' },
  { key: 'max', label: 'Max' },
  { key: 'size', label: 'Size' },
]
const boundsRows = computed(() =>
  source.value
    ? ['x', 'y', 'z'].map((axis) => ({
        axis: axis.toUpperCase(),
        min: source.value.bounds[axis + '_min'].toFixed(3),
        max: source.value.bounds[axis + '_max'].toFixed(3),
        size: (source.value.bounds[axis + '_max'] - source.value.bounds[axis + '_min']).toFixed(3),
      }))
    : [],
)
const actions = [
  { title: 'Binary STL', value: 'binary' },
  { title: 'ASCII STL', value: 'ascii' },
  { title: 'GeoJSON footprints', value: 'geojson' },
]
function clearResult() {
  result.value = ''
  error.value = ''
}
async function loadStl(selected) {
  clearResult()
  source.value = null
  const file = Array.isArray(selected) ? selected[0] : selected
  if (!file) return
  loading.value = true
  try {
    const stem = file.name.replace(/\.[^.]+$/, '')
    const parsed = parseSTL(await file.arrayBuffer(), stem)
    source.value = { stem, parsed, bounds: computeBounds(parsed.solids) }
    action.value = parsed.format === 'binary' ? 'ascii' : 'binary'
  } catch (failure) {
    error.value = `Could not read STL: ${failure.message}`
  } finally {
    loading.value = false
  }
}
async function exportFile() {
  if (!source.value || busy.value) return
  clearResult()
  exporting.value = true
  await new Promise((resolve) => setTimeout(resolve, 0))
  try {
    const { parsed, stem } = source.value
    if (action.value === 'geojson') {
      const collection = stlFootprints(parsed.solids, [
        Number.parseFloat(longitude.value),
        Number.parseFloat(latitude.value),
      ])
      downloadFile(JSON.stringify(collection), `${stem}_footprints.geojson`)
      result.value = `${collection.features.length} footprints exported. Downloaded: ${stem}_footprints.geojson.`
    } else {
      const content = action.value === 'binary' ? writeBinarySTL(parsed.solids) : writeAsciiSTL(parsed.solids)
      const filename = `${stem}_${action.value}.stl`
      downloadFile(content, filename, 'model/stl')
      result.value = `${parsed.triangleCount} facets exported. Downloaded: ${filename}.`
    }
  } catch (failure) {
    error.value = `Could not export STL: ${failure.message}`
  } finally {
    exporting.value = false
  }
}
const fileUpload = ref()
</script>

<template>
  <!-- Bố cục: Form đọc STL, hiển thị bounds bằng VaDataTable rồi chọn định dạng xuất; tọa độ gốc chỉ hiện khi xuất footprints GeoJSON. -->
  <section>
    <h1 class="page-title">STL Inspector & Converter</h1>
    <VaCard>
      <VaCardContent>
        <!-- Đầu vào và cấu hình xuất dùng control Vuestic; submit gọi hàm xử lý của trang, busy khóa thao tác khi đang chạy. -->
        <VaForm novalidate class="space-y-4" @submit.prevent="exportFile" @input="clearResult">
          <VaFileUpload
            id="stl-file"
            v-model="fileUpload"
            type="single"
            upload-button-text="STL file"
            file-types=".stl,model/stl"
            :disabled="busy"
            @update:modelValue="loadStl"
          />
          <VaProgressBar v-if="loading" indeterminate aria-label="Reading file" />
          <p v-if="source" class="text-sm text-secondary" data-testid="stl-summary">
            {{ source.parsed.format }} · {{ source.parsed.solids.length }} solids ·
            {{ source.parsed.triangleCount }} facets
          </p>
          <!-- Bảng hiển thị dùng VaDataTable của template; các giá trị đã đọc/định dạng được giữ nguyên. -->
          <VaDataTable v-if="source" :items="boundsRows" :columns="boundsColumns" aria-label="STL bounds" />
          <VaSelect
            id="stl-action"
            v-model="action"
            text-by="title"
            value-by="value"
            label="Output"
            aria-label="Output"
            :options="actions"
            :disabled="busy || !source"
            @update:modelValue="clearResult"
          />
          <template v-if="action === 'geojson'">
            <VaInput
              id="stl-latitude"
              v-model="latitude"
              label="Origin latitude"
              input-aria-label="Origin latitude"
              type="number"
              step="any"
              min="-89.999999"
              max="89.999999"
              required
              :disabled="busy"
            />
            <VaInput
              id="stl-longitude"
              v-model="longitude"
              label="Origin longitude"
              input-aria-label="Origin longitude"
              type="number"
              step="any"
              min="-180"
              max="180"
              required
              :disabled="busy"
            />
          </template>
          <VaButton type="submit" color="primary" :disabled="!source || busy" :loading="exporting">Export</VaButton>
        </VaForm>
        <!-- Thông báo đọc/xuất dữ liệu nằm gần thao tác liên quan; điều kiện v-if quyết định lúc hiển thị. -->
        <VaAlert v-if="error" color="danger" class="mt-4" role="alert" data-testid="tool-error">{{ error }}</VaAlert>
        <VaAlert v-if="result" color="success" class="mt-4" role="status" data-testid="tool-result">{{
          result
        }}</VaAlert>
      </VaCardContent>
    </VaCard>
  </section>
</template>
